"""Generate Step 7 documentation from measured routes, metrics and test evidence."""
from pathlib import Path
import json,argparse,xml.etree.ElementTree as ET
import pandas as pd
B=Path(__file__).resolve().parents[1];ROOT=B.parent


def table(frame):
    # No optional tabulate dependency required.
    header='| '+' | '.join(frame.columns)+' |'
    separator='| '+' | '.join(['---']*len(frame.columns))+' |'
    return '\n'.join([header,separator]+['| '+' | '.join(f'{v:.6f}' if isinstance(v,float) else str(v) for v in row)+' |' for row in frame.itertuples(index=False,name=None)])


def document(output):
    comparison=pd.read_csv(output/'classifier_vs_viterbi.csv');runtime=pd.read_csv(output/'runtime_by_trip.csv',dtype={'trip_id':str})
    per_trip=pd.read_csv(output/'per_trip_comparison.csv',dtype={'trip_id':str})
    configuration=json.loads((output/'configuration.json').read_text());verified=json.loads((output/'verification.json').read_text())
    meta=json.loads((output/'run_metadata.json').read_text())
    suites=list(ET.parse(output/'pytest-results.xml').getroot().iter('testsuite'))
    tests={key:sum(int(s.get(key,0)) for s in suites) for key in ['tests','failures','errors','skipped']}
    baseline=comparison.set_index('variant').loc['classifier'];decoded=comparison.set_index('variant').loc['viterbi']
    change=(decoded.top1_accuracy-baseline.top1_accuracy)*100
    paired=per_trip.pivot(index='trip_id',columns='variant',values='top1_accuracy')
    differences=(paired.viterbi-paired.classifier)*100
    per_trip_change='; '.join(f'{trip}: {value:+.3f} pp' for trip,value in differences.items())
    breaks=[]
    for folder in sorted((output/'trips').iterdir()):
        d=pd.read_parquet(folder/'decoded.parquet')
        breaks.extend(d.loc[d.break_reason.ne(''),'break_reason'].tolist())
    break_counts=pd.Series(breaks).value_counts().rename_axis('reason').reset_index(name='observations')
    commands=r'''cd .\PathSnap\laptop1_backend
.\.venv\Scripts\python.exe scripts\decode_step7.py
.\.venv\Scripts\python.exe scripts\report_step7.py
.\.venv\Scripts\python.exe -m pytest tests\test_step7.py -q
.\.venv\Scripts\python.exe scripts\verify_step7.py
.\.venv\Scripts\python.exe -m pytest -q --junitxml=outputs\step7\pytest-results.xml
.\.venv\Scripts\python.exe scripts\document_step7.py'''
    lines=['# Step 07: HMM and Viterbi route reconstruction',
      '## Objective, boundaries and executed result',
      'Use the frozen tuned Random Forest to choose coherent directed road sequences rather than independent candidate winners. Only Step 7 is implemented. Existing features, probabilities, original road IDs, trained classifiers and Steps 1–6 documentation/results remain intact. No training, optimisation, candidate regeneration, new extraction, evaluator-data processing, API, UI, final Folium application or deployment ZIP was performed.',
      f"Actual student-test result: {int(runtime.observations.sum())} observations across {len(runtime)} trips; {int(runtime.decoded.sum())} matched, {int(runtime.unmatched.sum())} unmatched, {int(runtime.segments.sum())} separate decoded segments. Qualified candidate-present Top-1 changed from {baseline.top1_accuracy:.6%} to {decoded.top1_accuracy:.6%}, a measured {change:+.6f} percentage-point change. This is observation matching against qualified heuristic references, not full-route ground-truth accuracy.",
      '## Inputs, reuse and isolation',
      'Primary artifact: models/step6/random_forest_tuned.joblib, verified against the Step 6 artifact manifest. The pipeline retains its exact 25-feature order and learned finite-value guard/median imputer/missing indicators. Its independent binary positive-class probabilities are reused from outputs/step6/student_predictions/random_forest/ only when the model and feature-file hashes agree. Candidate identities join one-to-one to the unchanged 29-column identifier-plus-feature table. Fresh inference is available as a fallback, with Pipeline.fit disabled. No classifier is fitted.',
      'The decoder sees only four state columns (gps_observation_index, candidate_arc_id, position_along_arc, positive_probability) and four observation columns (longitude, latitude, timestamp_s, displacement_m). Extra columns, including labels or reference arc IDs, are rejected. Graph input is the saved Step 2 road_arcs table, not the reference route. Existing Step 3 observations supply original index order, time and geodesic displacement. Byte hashes protect prior references/artifacts; reference values do not influence prediction. Frozen Step 5 labels/alignment are read by report_step7.py only after all ten completed prediction checkpoints exist.',
      '## Mathematical formulation and assumptions',
      r'Hidden state $s_t$ is an original directed candidate arc and its projected fractional position $u_t\in[0,1]$. For classifier score $p_t(s)$, clip to $q_t(s)=\min(1-\epsilon,\max(\epsilon,p_t(s)))$ and use $e_t(s)=\log q_t(s)-\log\sum_jq_t(j)$. Independent binary scores are not GPS likelihoods. Candidate normalization makes state potentials sum to one for each observation and changes no within-observation ranking; it does not establish calibration or generative emission probabilities.',
      r'For distinct arcs (or backward progress on one arc), directed travel distance is $D=(1-u_a)L_a+d(\mathrm{to}(a),\mathrm{from}(b))+u_bL_b$. For forward progress on the same arc, $D=(u_b-u_a)L_a$. Arc weights are saved WGS84 geodesic endpoint lengths; position fractions come from the existing straight projected segments. Their small projection/geodesic discrepancy is inherited, not silently recomputed. Full intermediate arcs use original IDs.',
      r'Transition log potential is $T(a,b)=-|D-d_{GPS}|/\beta$ if the directed route is feasible and $D\le v_{max}\Delta t+\mathrm{slack}$; otherwise it is $-\infty$. This uses exp-distance-agreement potentials with hard topology/movement constraints. Transition rows are deliberately not normalized over truncated candidate sets, so dead ends are not rewarded merely for having fewer successors. The implementation is an HMM-style conditional chain score, not a calibrated generative model or posterior probability estimator.',
      r'Viterbi uses $V_t(j)=e_t(j)+\max_i[V_{t-1}(i)+T(i,j)]$ and backpointers. Segment initial score is $e_0(j)-\log K_0$ (uniform initial prior). States are sorted by original arc ID; exact ties take the first predecessor and first terminal state. This gives deterministic local/terminal tie handling, not a claim of globally lexicographically smallest tied paths. All calculations remain in log space; zero scores are clipped before logging.',
      '## Frozen configuration and rationale',
      '```json\n'+json.dumps(configuration,indent=2)+'\n```',
      'No decoder parameter search was conducted. The five-second boundary and 50 m/s (180 km/h) ceiling reuse prior cleaning conventions; the 75 m additive movement allowance accommodates noisy projections and the 50 m distance-agreement scale is a conservative engineering default. Epsilon prevents log(0). These settings were saved before student scoring and were never changed in response to student labels. Future tuning must use grouped training validation and freeze a separate configuration before any new student evaluation.',
      '## Directed graph, shortest paths and loops',
      'DirectedRouter builds directed adjacency from valid and zero-length connector arcs. Invalid endpoints/geometries or nonfinite/negative lengths are excluded. Parallel arcs preserve original IDs; shortest distance wins and equal-distance discovery follows sorted arc IDs and node heap order. The implementation does not infer bidirectional travel or turn restrictions absent from the dataset.',
      'Strongly connected components and their condensation DAG distinguish proven directed unreachability from bounded-search failure. Bounded Dijkstra caches at most 1,024 source trees; reachable-component results have a separate bounded source cache. The absolute cutoff is 50×5+75=325 m, and at most 4,000 nodes are settled per search. Per-transition speed bounds can be tighter. A distance-bound or node-budget failure is reported separately from topological disconnection. No all-pairs path matrix is computed.',
      'Forward travel on the same arc needs no endpoint detour. Backward progress requires a real directed loop from the arc end to its start; its path can contain that arc again. Different arcs sharing an endpoint need zero intermediate arcs. Otherwise actual shortest directed intermediate arc IDs are reconstructed. Zero-length connectors are legal. No negative weights are permitted. Cache statistics, bounded failures and peak sampled process RSS are saved.',
      '## Boundaries and output meanings',
      'A trip starts a new chain. Invalid coordinates/nonfinite timestamps or no usable candidates produce explicit unmatched observation rows and close the previous chain. Nonpositive time intervals, gaps above five seconds, nonfinite displacement and excessive GPS movement close the previous chain and restart at the current usable observation. If every transition from all currently surviving DP states is infeasible, the earlier segment is backtracked and a new segment starts with reason no_feasible_transition. A restart can reflect reachability, bounds or accumulated DP constraints; it does not by itself prove disconnected physical roads.',
      'Three outputs are distinct: decoded.parquet has one selected candidate or unmatched row per original GPS observation; transitions.parquet contains feasible selected links within a segment, their partial-arc travel distance and ordered route_arcs; route_arcs.parquet contains the full per-segment arc sequence including intermediate occurrences and genuine loops. Repeated forward observations on one arc share one route occurrence. Entry/exit fractions reside in the selected candidate rows referenced by links; the first/last road geometry is only partially traversed. Full arc IDs/diagnostic drawings are not a claim that every endpoint of those end arcs was driven. Segment IDs must never be joined by an invented link.',
      table(break_counts),
      '## Evaluation definitions and actual pooled results',
      'Both variants use identical fixed denominators. Top-1 counts correctly selected original arc IDs among qualified reference-present observations, including an unmatched decoder output as failure. Miss-aware accuracy includes qualified candidate misses; correct/raw additionally counts ambiguous, excluded and unalignable observations in its denominator and is coverage-sensitive. Neither is a physically independently labelled route accuracy. Student references were already used for development evaluation in prior stages, so these are not untouched final-evaluator estimates.',
      table(comparison[['variant','raw_observations','qualified_alignments','candidate_present','candidate_misses','correct','top1_accuracy','top1_including_candidate_misses','correct_per_raw_observation']]),
      'Classifier candidate Macro F1/log loss remain the Step 6 binary-probability metrics. Viterbi returns a MAP sequence, not posterior marginals; no invented decoded log loss, probability calibration or candidate-classification F1 is reported. Candidate availability has not changed.',
      '## Continuity and route plausibility',
      'Assessable pairs are adjacent original observations with valid short time intervals, usable displacement below the configured bound and predictions for both observations. Direct continuity means forward progress on one arc or direct legal endpoint adjacency between different arcs. Topological unreachability is evaluated independently of speed/distance bounds. Feasibility additionally requires a valid bounded route and movement constraint. Cross-segment pairs remain visible; perfect feasibility inside retained segments is a construction invariant, not evidence that every trip became one continuous route.',
      table(comparison[['variant','assessable_pairs','direct_continuity','topologically_unreachable','feasible_pairs','infeasible_pairs','bounded_feasibility','cross_segment_pairs','within_segment_infeasible','network_distance_sum_m']]),
      'Full route continuity is checked by matching every consecutive arc endpoint within each segment. Distances are plausible under the configured ceiling/allowance; this does not validate real turn legality, travel time, unseen curves or intermediate-road correctness. Some wrong but topologically plausible roads can be reinforced by the sequence model. Per-trip tables expose improvements and degradations rather than hiding them in a pooled score.',
      table(per_trip[['trip_id','variant','top1_accuracy','direct_continuity','topologically_unreachable','infeasible_pairs','cross_segment_pairs']]),
      f'Per-trip Top-1 changes: {per_trip_change}. Improvements occurred on {int(differences.gt(0).sum())} trips, degradation on {int(differences.lt(0).sum())}, and no change on {int(differences.eq(0).sum())}. Connectivity and distance consistency can reinforce a geometrically plausible wrong candidate, so continuity improvement does not guarantee per-trip reference agreement.',
      '## Runtime and resources',
      f"Total recorded decoding time: {runtime.decode_seconds.sum():.3f} s; graph construction: {runtime.graph_seconds.sum():.3f} s; summed trip processing: {runtime.total_seconds.sum():.3f} s. Latest trip-loop invocation: {meta['invocation_seconds']:.3f} s (excludes initial model load/protected-file hashing). Peak sampled process RSS: {runtime.peak_process_rss_mib.max():.3f} MiB, not incremental decoder-only memory. All {int(runtime.probabilities_reused.sum())} trips reused validated cached classifier probabilities. Serial decoding uses no heavy concurrent jobs and no new dependencies.",
      table(runtime[['trip_id','observations','decoded','segments','decode_seconds','graph_seconds','peak_process_rss_mib','searches','cache_hits','budget_exhaustions']]),
      '## Source modules and function contracts',
      '| File / function | Inputs → outputs / purpose |\n|---|---|\n| src/pathsnap/hmm.py: DecoderConfig, log_emissions, emission_states | Validated frozen settings; binary scores → finite state log potentials; exact feature/probability identities → allowlisted states |\n| src/pathsnap/routing.py: DirectedRouter, route, between_nodes | Saved arc-indexed graph, arc IDs/fractions or node IDs → distance, original arc tuple and explicit feasibility reason |\n| src/pathsnap/transitions.py: transition | Two candidates, elapsed time/displacement, router/config → log potential and route result |\n| src/pathsnap/viterbi.py: decode | Allowlisted observations/states + router/config → selected observation rows, links, reconstructed route occurrences, attempted-pair diagnostics |\n| src/pathsnap/route_evaluation.py | Selected rows + separate labels → fixed-denominator matching; selected pairs + graph → topology/movement diagnostics |\n| scripts/decode_step7.py | Frozen pipeline and precomputed inputs → checksummed per-trip inference-only checkpoints/runtime; no reference values in prediction |\n| scripts/report_step7.py | Completed predictions + frozen evaluation labels → comparison/per-trip CSVs and static geographic diagnostics |\n| scripts/verify_step7.py | Saved inputs/checkpoints → independent metrics, route/identity/probability checks and one small real-trip deterministic replay |\n| scripts/document_step7.py | Measured reports + JUnit/verification → detailed reference, summary and three current-status READMEs |',
      '## Saved artifacts and diagnostic examples',
      'outputs/step7/configuration.json freezes settings; protected_artifacts.json records previous-stage checksums; run_metadata.json records model/code identity and non-training policy. trips/<trip>/ contains probabilities.parquet, classifier_selected.parquet, decoded.parquet, transitions.parquet, route_arcs.parquet, transition_diagnostics.parquet, classifier_pair_diagnostics.parquet, viterbi_pair_diagnostics.parquet and complete.json. The completion stamp stores input/code/config/version identities, output checksums and resource/timing metadata. No original model or pipeline file is rewritten.',
      'Aggregate outputs: classifier_vs_viterbi.csv, per_trip_comparison.csv, runtime_by_trip.csv, verification.json, pytest-results.xml, test-results.txt and STEP7_SUMMARY.md. comparison.png shows actual accuracy/continuity. 00000000_route_diagnostic.png, 00000007_route_diagnostic.png and 00000009_route_diagnostic.png show original GPS, classifier candidate arcs, Viterbi candidates, intermediate arcs and explicit breaks. These are static longitude/latitude Matplotlib diagnostics, not the Step 8 Folium application. No tiles or internet download is required.',
      '## Exact Windows PowerShell execution and recovery',
      '```powershell\n'+commands+'\n```',
      'Run decode_step7.py again to resume: complete trip identities and all output checksums are verified before reuse. An interrupted/incomplete or corrupted trip is decoded again; completed valid trips are not. Per-trip Parquet writes use temporary files and replacement; complete.json is the final commit marker. If model/configuration/input/code/version identity changes, use a new output directory; no earlier comparison is silently mixed. Report-only files can be regenerated without decoding. Verification replays only the smallest real trip and never retrains a classifier. An actual second runner invocation reused all ten verified trip checkpoints and decoded zero trips again; resume_verification.json records this result. initial_run_metadata.json retains the first complete invocation timing, while run_metadata.json describes the latest resume invocation.',
      r'Optional frozen HGB comparison: `.\.venv\Scripts\python.exe scripts\decode_step7.py --model hist_gradient_boosting --output outputs\step7_hgb` followed by the reporting/verification scripts with that output path. This optional run was not executed for Step 7; no HGB decoder result is claimed. A custom `--config` JSON must contain only DecoderConfig field names and must use a distinct output directory. Do not tune it using student references.',
      '## Tests and verification',
      '```json\n'+json.dumps(dict(tests=tests,verification=verified),indent=2)+'\n```',
      'Focused tests cover exact shortest distances against NetworkX, legal direction, endpoint turns, partial arcs, same-arc backward loops, parallel/zero-length arcs, unreachable versus budget/distance bounds, cache eviction, missing candidates, invalid coordinates/time/gaps, implausible movement, zero/tiny/invalid probabilities, deterministic ties and brute-force global optimum. Leakage tests reject extra label columns and mismatched identities. Evaluation tests keep unmatched predictions and candidate misses in fixed denominators. The real frozen pipeline reloads/predicts with fitting disabled; two-thread floating summation is compared within 1e-13 relative/1e-15 absolute tolerance.',
      'Verification rechecks all prior protected files and completed output checksums; every selected arc belongs to its observation candidates; every selected link agrees with its current directed shortest path, partial distance, score and time; each within-segment full route connects; per-trip/pooled metrics match saved predictions. One preselected smallest real trip must replay identically. Classifier-only accuracy must agree with Step 6. All previous 126 tests remain in the full suite.',
      '## Limitations and Step 8 readiness',
      'Fixed uncalibrated potentials and heuristic reference labels limit interpretation. Directed topology supplies no turn restrictions, road classes or speed-specific legal limits. Bounded searches can deliberately reject reachable long detours. The 325 m absolute bound follows the current gap/speed/slack assumptions. Multiple physically plausible intermediate routes can share distance; deterministic shortest-route choice is not reference-route recovery. Candidate misses cannot be repaired by selecting among existing states, though intermediate arcs can restore between-observation continuity. Temporal/disconnected breaks remain explicit and must remain separate in a future renderer.',
      'The reusable decoder, frozen configuration, segment-aware routes and verified diagnostics are ready for separately approved Step 8 visualisation/integration work. No final Folium UI, FastAPI, Streamlit, two-laptop integration or deployment ZIP is implemented. Earlier step references remain unchanged. Review/disclose AI assistance according to the event policy and be prepared to explain the scoring assumptions and actual experiments.',
      'Changelog — 2026-11-18: implemented Step 7 inference-only directed routing, log-space Viterbi, resumable route artifacts, frozen-reference evaluation, static geographic diagnostics, tests and documentation. Stop after Step 7.']
    text='\n\n'.join(lines)+'\n'
    (ROOT/'docs/steps/STEP_07_README.md').write_text(text,encoding='utf-8');(output/'STEP7_SUMMARY.md').write_text(text,encoding='utf-8')
    for path,prefix in [(ROOT/'README.md','docs/steps/'),(B/'README.md','../docs/steps/'),(ROOT/'laptop2_frontend/README.md','../docs/steps/')]:
        old=path.read_text(encoding='utf-8');marker='\n<!-- STEP7_CURRENT -->'
        if marker in old:old=old.split(marker)[0]
        old=old.replace('## Current status: Step 6 completed','## Historical Step 6 completion record')
        old=old.replace('**Steps 1–6 are implemented:**','**Steps 1–7 are implemented:**').replace('(Steps 1–6)','(Steps 1–7)')
        old=old.replace('Steps 1–6 are complete; Step 7 requires explicit approval.','Steps 1–7 are complete; Step 8 requires explicit approval.')
        old=old.replace('Steps 1–6 maintain this directory and documentation only.','Steps 1–7 maintain this directory and documentation only.')
        old=old.replace('HMM/Viterbi, API server and inference service remain pending.','Step 7 adds HMM/Viterbi route reconstruction. API server and inference service remain pending.')
        old=old.replace('- [ ] Step 7 HMM/Viterbi; not started.','- [x] Step 7 HMM/Viterbi; see current reference.')
        old=old.replace('Step 6 Bayesian optimisation; stop before Step 7','Step 6 Bayesian optimisation → Step 7 HMM/Viterbi; stop before Step 8')
        old=old.replace('Bayesian classifier optimisation is now complete. Decoding and the distributed application remain pending.','Bayesian classifier optimisation and HMM/Viterbi decoding are complete. The distributed application remains pending.')
        addition=f"\n\n## Current status: Step 7 completed\n\n[Step 7 detailed reference]({prefix}STEP_07_README.md). The frozen tuned Random Forest supplies emissions to directed, bounded shortest-path transitions and deterministic log-space Viterbi. {len(runtime)} student-test trips / {int(runtime.observations.sum())} observations decoded into {int(runtime.segments.sum())} explicit segments. Qualified candidate-present Top-1: classifier {baseline.top1_accuracy:.6%}; Viterbi {decoded.top1_accuracy:.6%} ({change:+.6f} percentage points). See the detailed report for candidate-miss coverage, breaks, unreachable pairs, per-trip results and limitations. No student references chose decoder parameters; no model was retrained. Steps 1–6 artifacts and step READMEs remain unchanged.\n\nNew modules: hmm.py, routing.py, transitions.py, viterbi.py and route_evaluation.py. Scripts: decode_step7.py, report_step7.py, verify_step7.py and document_step7.py; exact PowerShell commands and input/output contracts are in the linked reference. Outputs are under laptop1_backend/outputs/step7/, including selected candidates, intermediate route arcs, topology diagnostics, runtime, three static geographic examples, verification and STEP7_SUMMARY.md. No dependencies added; Laptop 2 remains a documentation-only placeholder.\n\nFull suite: {tests['tests']} tests, {tests['failures']} failures, {tests['errors']} errors, {tests['skipped']} skipped. Decoding {runtime.decode_seconds.sum():.3f} s; peak sampled process RSS {runtime.peak_process_rss_mib.max():.3f} MiB.\n\n- [x] Step 7 HMM/Viterbi, directed route reconstruction, evaluation, verification and documentation.\n- [ ] Step 8 final Folium visualisation/application; not started. API/UI, two-laptop integration and deployment remain pending.\n\nChangelog — 2026-11-18: completed Step 7 with the frozen classifier and existing feature/network/probability artifacts. Stop here; Step 8 requires explicit approval.\n"
        path.write_text(old+marker+addition,encoding='utf-8')
    print('Step 7 reference, summary and three READMEs updated from actual artifacts.')


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,default=B/'outputs/step7');a=p.parse_args();document(a.output)
